#!/usr/bin/env bash
# =============================================================================
# run_sim_streams.sh —— 实时层「虚拟数据流」验证（只读、不触网、不碰账户/数据）
#
#   把脚本化构造的 Snapshot 序列喂进【容器内现役】 realtime 包（/app/realtime），
#   断言 6+1 类行为，全内存、纯只读：
#     A 盘中动态重排（模型分接近时便宜+买盘强票爬升到追高+偏贵票之前）
#     B 重排有界（模型分差大时盘中极端量也翻不动次序——模型锚定 cap）
#     C 候选池封闭（expected_return<=0/无分票绝不入榜）
#     D A股 T+1（当日买入暴跌也不出场）
#     E 次日 5 级出场按优先级触发（止损/止盈/移动止盈/破位/到期）
#     F 入场过滤（追高票被跳过，顺延买下一名）
#     G 优雅降级（缺 VWAP/盘口量退化为纯模型序，不崩）
#
#   跑的是【容器内现役 /app/realtime 代码】——即当前引擎进程用的同一份逻辑。
#   sim_streams.py 只解码到容器 /tmp（临时态），不进镜像、不落 git，docker rm 即失。
#   全程不写 paper_state.json（用独立临时目录）、不推送真消息（FakeNotifier）。
#
# 用法（宿主机 /www/A，zsh 直接跑，勿加 ! 前缀）：bash run_sim_streams.sh
# 退出码 0=全通过；非 0=有 [FAIL]（见输出）。
# =============================================================================
set -u
CT="a-scheduler-1"
SRC_MD5="3794e2f2a4350d7cc8f16346a956815d"   # 本地权威版本 md5，供落地一致性核对

echo "=================================================================="
echo " 虚拟数据流验证  $(date '+%F %T')  容器=$CT"
echo "=================================================================="

# ---- 前置：容器在跑？----
if docker inspect -f '{{.State.Running}}' "$CT" 2>/dev/null | grep -q true; then
  echo "容器 $CT 运行中。"
else
  echo "[abort] 容器 $CT 未运行——请先 docker compose up -d scheduler"; exit 1
fi

# ---- 1) 解码测试脚本进容器 /tmp（base64，规避中文/特殊字符传输损坏）----
echo "-- 解码 sim_streams.py 进容器 /tmp --"
docker exec -i "$CT" sh -c 'base64 -d > /tmp/sim_streams.py' <<'B64_EOF'

B64_EOF

# ---- 2) 落地一致性核对（可选）：容器内 md5 == 本地权威 md5 ----
GOT="$(docker exec "$CT" md5sum /tmp/sim_streams.py 2>/dev/null | awk '{print $1}')"
if [ "$GOT" = "$SRC_MD5" ]; then
  echo "  [ok] 容器内 sim_streams.py md5 命中本地权威版本（$GOT）"
else
  echo "  [warn] md5 不一致 got=$GOT want=$SRC_MD5（传输可能有损，仍尝试运行）"
fi

# ---- 3) 语法自检（ast.parse，不 import 现役模块即可查语法）----
echo "-- ast.parse 语法自检 --"
docker exec "$CT" python3 -c "import ast,sys; ast.parse(open('/tmp/sim_streams.py').read()); print('  [ok] AST OK')" \
  || { echo "  [abort] sim_streams.py 语法错误"; exit 2; }

# ---- 4) 直接运行镜像内现役测试模块；/tmp 内嵌副本不再作为执行源 ----
echo "-- 运行镜像内 realtime.sim_streams（下方 PASS/FAIL 为断言结果）--"
docker exec -e PYTHONPATH=/app "$CT" python3 -m realtime.sim_streams
RC=$?

echo ""
echo "=================================================================="
if [ "$RC" -eq 0 ]; then
  echo " ✅ 虚拟数据流全通过（现役 realtime 逻辑符合预期）"
else
  echo " ❌ 有断言失败（见上方 [FAIL] 行），RC=$RC"
fi
echo " 提示：断言直接运行镜像内 /app/realtime/sim_streams.py；/tmp 旧载荷不参与执行。"
echo "=================================================================="
exit $RC

